CREATE TABLE t2(x,y);WITH a(v)AS(VALUES(5),(1),(3),(2),(4),(6)),b(v)AS(VALUES(3),(4),(2),(1),(5),(6)) INSERT INTO t2 SELECT a.v,b.v FROM a,b;CREATE TABLE t3(a,b);INSERT INTO t3 VALUES(2,2),(4,4),(5,5);CREATE UNIQUE INDEX t3i1 ON t3(a ASC);CREATE UNIQUE INDEX t3i2 ON t3(b DESC);CREATE INDEX i1 ON t2(y ASC,x ASC);